import * as React from 'react'
import * as ReactDOM from 'react-dom'
import * as jsxRuntime from 'react/jsx-runtime'
import { usePluginContext } from './context'

declare global {
  // eslint-disable-next-line no-var
  var __LLBOT_WEBUI__: { modules: Record<string, unknown> }
}

/**
 * The modules plugin code gets for its bare imports. The import map in index.html points those specifiers
 * at the shims generated by pluginSharedShims() in vite.config.ts, which re-export what is set here: the
 * WebUI's own React, so plugin components and the WebUI share hooks and context.
 */
export function installSharedModules() {
  globalThis.__LLBOT_WEBUI__ = {
    modules: {
      'react': React,
      'react/jsx-runtime': jsxRuntime,
      'react-dom': ReactDOM,
      '@luckylillia/plugin-sdk/webui': { usePluginContext },
    },
  }
}
